// refactor obligation to better handle operations
module protocol::obligation;

use protocol::ctoken::CToken;
use protocol::ctoken_table::{Self, CTokenTable};
use protocol::debt::{Self, Debt};
use protocol::error;
use std::type_name::{Self, TypeName};
use sui::balance::Balance;
use protocol::wit_table::{Self, WitTable};
use math::float::Decimal;

public struct ObligationOwnerCap has key, store {
    id: UID,
    obligation_id: ID,

    // redundant fields, but makes query slightly easier
    market_type: TypeName,
    market_id: ID,
}

public struct Obligation<phantom MarketType> has key, store {
    id: UID,
    // with market id, no need to track version
    lending_market_id: ID,
    debts: WitTable<ObligationDebts, TypeName, Debt>,
    ctokens: CTokenTable,

    emode_group: u8,
}

public fun id(self: &ObligationOwnerCap): ID {
    self.obligation_id
}

public(package) fun emode_group<MarketType>(self: &Obligation<MarketType>): u8 {
    self.emode_group
}

public(package) fun debts<MarketType>(
    self: &Obligation<MarketType>,
): &WitTable<ObligationDebts, TypeName, Debt> {
    &self.debts
}

public(package) fun market_id<MarketType>(self: &Obligation<MarketType>): ID {
    self.lending_market_id
}

public(package) fun new<MarketType>(
    lending_market_id: ID,
    emode_group: u8,
    ctx: &mut TxContext,
): (Obligation<MarketType>, ObligationOwnerCap) {
    let obligation = Obligation {
        id: object::new(ctx),
        lending_market_id,
        debts: wit_table::new(ObligationDebts {}, true, ctx),
        ctokens: ctoken_table::new(ctx),
        emode_group,
    };

    let cap = ObligationOwnerCap {
        id: object::new(ctx),
        obligation_id: object::id(&obligation),
        market_type: type_name::with_defining_ids<MarketType>(),
        market_id: lending_market_id,
    };
    (obligation, cap)
}

public(package) fun accrue_interest<MarketType>(
    self: &mut Obligation<MarketType>,
    name: TypeName,
    asset_borrow_index: Decimal,
): &mut Debt {
    let debt = wit_table::borrow_mut(ObligationDebts {}, &mut self.debts, name);
    debt.accrue_interest(asset_borrow_index);
    debt
}

public(package) fun deposit_ctoken<MarketType, CoinType>(
    self: &mut Obligation<MarketType>,
    ctoken: Balance<CToken<MarketType, CoinType>>,
) {
    assert!(
        !self.debts.contains(type_name::with_defining_ids<CoinType>()),
        error::obligation_deposit_borrowed_asset(),
    );
    if (!self.ctokens.is_supporting_collateral<MarketType, CoinType>()) {
        self.ctokens.support_collateral_token<MarketType, CoinType>();
    };
    self.ctokens.join_ctoken(ctoken);
}

public(package) fun withdraw_ctokens<MarketType, CoinType>(
    self: &mut Obligation<MarketType>,
    amount: u64,
): Balance<CToken<MarketType, CoinType>> {
    assert!(
        self.ctokens.is_supporting_collateral<MarketType, CoinType>(),
        error::obligation_withdraw_no_deposit(),
    );
    self.ctokens.split_ctoken<MarketType, CoinType>(amount)
}

/// Try borrow the asset, increase the debt. Returns the latest asset debt.
public(package) fun try_borrow_asset<MarketType, CoinType>(
    self: &mut Obligation<MarketType>,
    amount: u64,
    asset_borrow_index: Decimal,
): Decimal {
    let name = type_name::with_defining_ids<CoinType>();

    let amount = math::float::from(amount);

    if (!self.debts.contains(type_name::with_defining_ids<CoinType>())) {
        // no borrow before, init borrow

        // do not allow borrowing of collateral asset, mess up book keeping
        assert!(
            !self.ctokens.is_supporting_collateral<MarketType, CoinType>(),
            error::obligation_borrow_collateral_asset(),
        );

        wit_table::add(
            ObligationDebts {},
            &mut self.debts,
            name,
            debt::new(amount, asset_borrow_index),
        );

        return amount
    };

    let debt = self.accrue_interest(type_name::with_defining_ids<CoinType>(), asset_borrow_index);

    // this is safe to do because it has accrued interest before
    debt.unsafe_increase(amount);
    debt.unsafe_debt_amount()
}

/// Obligation repays debt, returns 
public(package) fun repay_debt<MarketType, CoinType>(
    self: &mut Obligation<MarketType>,
    amount: u64,
    asset_borrow_index: Decimal,
): u64 {
    let _ = self.accrue_interest(type_name::with_defining_ids<CoinType>(), asset_borrow_index);
    self.unsafe_repay_debt_only<MarketType, CoinType>(amount)
}

/// Checks the invariants after borrow or repay that must be met
public(package) fun enforce_post_borrow_repay_invariant<MarketType, CoinType>(
    self: &Obligation<MarketType>,
    min_borrow_amount: u64
) {
    let coin_type = type_name::with_defining_ids<CoinType>();

    if (!self.has_debt<MarketType>(coin_type)){
        return
    };

    let current_debt = self.debt<MarketType>(coin_type).unsafe_debt_amount();
    assert!(current_debt.ge_u64(min_borrow_amount), error::obligation_borrow_below_min());
}

/// Directly updating the debt repay, without checking if interest is up to date.
/// The caller makes sure the obligation interest is already updated to date
public(package) fun unsafe_repay_debt_only<MarketType, CoinType>(
    self: &mut Obligation<MarketType>,
    amount: u64,
): u64 {
    let name = type_name::with_defining_ids<CoinType>();
    let debt = wit_table::borrow_mut(ObligationDebts {}, &mut self.debts, name);

    let debt_amount = debt.unsafe_debt_amount().ceil();

    let residual = if (debt_amount <= amount) {
        debt.cleared();

        // repay a bit more than actually owned, almost neglegible
        amount - debt_amount
    } else {
        debt.unsafe_decrease(math::float::from(amount));
        0
    };

    if (!debt.has_debt()) {
        wit_table::remove(ObligationDebts {}, &mut self.debts, name);
    };

    residual
}

/// Make sure the type name is ctoken type
public fun ctoken_amount_by_coin<MarketType>(
    self: &Obligation<MarketType>,
